actions.script:
import java.sql.Connection import java.sql.ResultSet import java.sql.Statement
try { // ---- host / JVM, same source as the built-in system dashboard ---- Map smap = ec.factory.getStatusMap(true) Map util = (Map) smap.Utilization Map heap = (Map) smap.Heap Map nonHeap = (Map) smap.NonHeap Map disk = (Map) smap.Disk Map sys = (Map) smap.System Map javaRuntime = (Map) smap.JavaRuntime Map javaStats = (Map) smap.JavaStats
BigDecimal mb = new BigDecimal(1024 * 1024) BigDecimal heapUsedBytes = ((heap.Used ?: 0) as BigDecimal) * mb BigDecimal heapMaxBytes = ((heap.Max ?: 0) as BigDecimal) * mb BigDecimal heapCommittedBytes = ((heap.Committed ?: 0) as BigDecimal) * mb BigDecimal nonHeapUsedBytes = ((nonHeap.Used ?: 0) as BigDecimal) * mb BigDecimal diskTotalBytes = ((disk.Total ?: 0) as BigDecimal) * mb BigDecimal diskUsedBytes = diskTotalBytes - (((disk.Free ?: 0) as BigDecimal) * mb)
// this process' JVM/disk view stands in for "host" - there is no // node-exporter to report the machine outside this container host.cpuPercent = util.LoadPercent ?: 0 host.load1 = sys.Load ?: 0 host.memUsedBytes = heapUsedBytes host.memTotalBytes = heapMaxBytes host.diskUsedBytes = diskUsedBytes host.diskTotalBytes = diskTotalBytes host.uptimeSeconds = ((javaRuntime.UptimeHours ?: 0) as BigDecimal) * 3600
String instanceName = System.getProperty('instance_purpose') ?: 'prod' jvms = [[instance: instanceName, heapUsedBytes: heapUsedBytes, heapMaxBytes: heapMaxBytes, heapCommittedBytes: heapCommittedBytes, nonHeapUsedBytes: nonHeapUsedBytes, threadCount: javaStats.ThreadCount ?: 0, gcTimeSeconds: javaStats.GcTimeSeconds ?: 0]]
// ---- postgres, queried directly - the same tables postgres_exporter reads ---- Connection con = ec.entity.getConnection('transactional') try { Statement stmt = con.createStatement() try { ResultSet rs = stmt.executeQuery('SELECT count(*) FROM pg_stat_activity') if (rs.next()) database.connections = new BigDecimal(rs.getLong(1)) rs.close()
rs = stmt.executeQuery("SELECT setting FROM pg_settings WHERE name = 'max_connections'") if (rs.next()) database.maxConnections = new BigDecimal(rs.getString(1)) rs.close()
rs = stmt.executeQuery(''' SELECT d.datname AS datname, count(a.pid) AS connections, pg_database_size(d.datname) AS size_bytes FROM pg_database d LEFT JOIN pg_stat_activity a ON a.datname = d.datname WHERE NOT d.datistemplate GROUP BY d.datname ORDER BY d.datname ''') List dbs = [] while (rs.next()) { dbs.add([name: rs.getString('datname'), connections: new BigDecimal(rs.getLong('connections')), sizeBytes: new BigDecimal(rs.getLong('size_bytes'))]) } rs.close() database.databases = dbs } finally { stmt.close() } } finally { con.close() }
available = true } catch (Throwable t) { ec.logger.warn("InfraMetrics error: ${t.message}", t) available = false message = "Metrics unavailable: ${t.message}" }
